import{_ as r,o as e,c as a,a0 as o}from"./chunks/framework.Czf8PZMA.js";const u=JSON.parse('{"title":"SECTION 05 12 00 — Structural Steel Framing（结构钢框架）★可直接投用完整条款版★","description":"","frontmatter":{},"headers":[],"relativePath":"guide/07-section-steel.md","filePath":"guide/07-section-steel.md","lastUpdated":null}'),d={name:"guide/07-section-steel.md"};function l(n,t,i,s,c,g){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="section-05-12-00-—-structural-steel-framing-结构钢框架-★可直接投用完整条款版★" tabindex="-1">SECTION 05 12 00 — Structural Steel Framing（结构钢框架）★可直接投用完整条款版★ <a class="header-anchor" href="#section-05-12-00-—-structural-steel-framing-结构钢框架-★可直接投用完整条款版★" aria-label="Permalink to &quot;SECTION 05 12 00 — Structural Steel Framing（结构钢框架）★可直接投用完整条款版★&quot;">​</a></h1><blockquote><p>📌 <strong>本文件是把 <code>02_钢结构框架</code> 的「05 12 00」展开成可投用的 MasterFormat 三段式完整条款</strong>（Part 1 General / Part 2 Products / Part 3 Execution），并内嵌<strong>中美标准对应</strong>与<strong>合规流程停点</strong>。</p><ul><li>用法：把本段复制进项目 SPEC，填 <code>[待定]</code> 处即可发出；Part 2/3 的验收项可进报价/采购合同。</li><li>依据：spec-agent 库真实模板条款 <code>[spec-agent 05]</code> + 钢结构源文档 <code>[源文档 05 12/05 50]</code> + <code>01_共享框架合规底座</code> §0.4 规范分布。</li><li>代码：MasterFormat 05 12 00 — Structural Steel Framing。</li></ul></blockquote><hr><h2 id="part-1-—-general-一般要求" tabindex="-1">PART 1 — GENERAL（一般要求） <a class="header-anchor" href="#part-1-—-general-一般要求" aria-label="Permalink to &quot;PART 1 — GENERAL（一般要求）&quot;">​</a></h2><h3 id="_1-1-章节范围-section-includes-章节包括" tabindex="-1">1.1 章节范围（Section Includes / 章节包括） <a class="header-anchor" href="#_1-1-章节范围-section-includes-章节包括" aria-label="Permalink to &quot;1.1 章节范围（Section Includes / 章节包括）&quot;">​</a></h3><ul><li>钢结构模块之<strong>结构钢框架与底盘</strong>：主梁/柱（W 型钢）、角钢/钢板次构件、剪力连接栓钉、模块间结构连接节点（螺栓/焊接/连接板）之<strong>委派设计、加工、安装、检测与防腐</strong>。</li><li>现场拼接节点、吊装临时锚固件、模块与基础之锚栓/连接界面。</li><li>横向关联：Division 01 33（提交）/01 43（QA）/01 66（吊装）、03 30（锚栓基础）、05 31（钢质楼板）、05 50（金属制品/吊点保护）、13 42（模块本体）、13 48（抗震连接）。</li></ul><h3 id="_1-2-引用文件-纳入合同与规范" tabindex="-1">1.2 引用文件（纳入合同与规范） <a class="header-anchor" href="#_1-2-引用文件-纳入合同与规范" aria-label="Permalink to &quot;1.2 引用文件（纳入合同与规范）&quot;">​</a></h3><ul><li><strong>AISC 360</strong>（结构钢建筑规范）+ AISC <em>Design, Fabrication and Erection</em>（加工安装执行基准）<code>[spec-agent 05]</code></li><li><strong>AISC S348 / RCSC</strong>（用 ASTM A325/A490 螺栓之结构连接）<code>[spec-agent 05]</code></li><li><strong>AWS D1.1/D1.1M</strong> 钢结构焊接规范；<strong>AWS D1.8/D1.8M</strong> 抗震补编（加州 D/E 级结构适用）</li><li><strong>ASTM A992/A992M</strong>、<strong>ASTM A36/A36M</strong>、<strong>ASTM A325/A490</strong>、<strong>ASTM A307 Gr.A + A153/A153M</strong>（镀锌）</li><li><strong>AISI S100 / S240</strong>（如需冷弯承重墙柱 CFS）</li><li>加州/联邦：<strong>CBC（Title 24 Part 2，基于 IBC）+ ASCE 7</strong>（抗震）、<strong>AISC 341</strong>（抗震设计）、<strong>HCD 25 §3032</strong>（检验频率）、<strong>HSC §19980</strong>（insignia）、<strong>CFC（Part 9）</strong> 防火、<strong>CEC（Part 6）</strong> 节能。</li><li>中美对应：<strong>GB/T 1591（Q355→A992）、GB/T 700（Q235→A36）、GB 50017（钢构）、GB 50011（抗震）、GB/T 13912（镀锌）</strong> ——详见下方 2.1「材料替换换算表」。</li></ul><h3 id="_1-3-提交要求-submittals" tabindex="-1">1.3 提交要求（Submittals） <a class="header-anchor" href="#_1-3-提交要求-submittals" aria-label="Permalink to &quot;1.3 提交要求（Submittals）&quot;">​</a></h3><ul><li>委派设计计算书 + <strong>加州执照结构工程师（SE）复核签字</strong>图纸副本（DAA 版=现场版）。</li><li>材料证书（mill certificate）——涵盖 ASTM 力学性能 + GB 成分对照。</li><li>焊接程序评定报告（PQR）+ 焊工资质（AWS/CWB）；扭矩标定记录；NDT 报告（UT/MT）。</li><li><strong>FAT 清单</strong>（出厂前）、<strong>ITP/检验试验计划</strong>。</li><li>防腐涂层/镀锌体系数据表。</li></ul><h3 id="_1-4-质量保证-qa" tabindex="-1">1.4 质量保证（QA） <a class="header-anchor" href="#_1-4-质量保证-qa" aria-label="Permalink to &quot;1.4 质量保证（QA）&quot;">​</a></h3><ul><li>制造厂须具 <strong>AISC-certified（Qc/Qa）</strong> 或等效出海焊接质量体系；具备<strong>加州赴厂检验接待能力</strong>（对标 CIMC-MBS 先例）。</li><li>第三方 QAA 持证检验；检率依 <strong>Title 25 §3032</strong>：新型号 100%→首10台全检→可降频至 25%。</li></ul><h3 id="_1-5-交货与存储-delivery-storage" tabindex="-1">1.5 交货与存储（Delivery/Storage） <a class="header-anchor" href="#_1-5-交货与存储-delivery-storage" aria-label="Permalink to &quot;1.5 交货与存储（Delivery/Storage）&quot;">​</a></h3><ul><li>运输按 Division 01 66 + Caltrans 限重限高；构件加固防变形；到货损伤如实记录并 NCR 关闭后方可安装。</li></ul><hr><h2 id="part-2-—-products-产品-材料" tabindex="-1">PART 2 — PRODUCTS（产品/材料） <a class="header-anchor" href="#part-2-—-products-产品-材料" aria-label="Permalink to &quot;PART 2 — PRODUCTS（产品/材料）&quot;">​</a></h2><h3 id="_2-1-材料替换换算表-中美对应-写入采购-★" tabindex="-1">2.1 材料替换换算表（中美对应，写入采购）★ <a class="header-anchor" href="#_2-1-材料替换换算表-中美对应-写入采购-★" aria-label="Permalink to &quot;2.1 材料替换换算表（中美对应，写入采购）★&quot;">​</a></h3><blockquote><p>美标=验收基准；中标为国内对标/采购选用。选材时逐项核对力学与工艺差异。</p></blockquote><table tabindex="0"><thead><tr><th>部位</th><th>美国标准（验收基准）</th><th>中国对应规范</th><th>差异处理</th></tr></thead><tbody><tr><td>主框架 W 型钢</td><td><strong>ASTM A992</strong>（≥50ksi/345MPa）</td><td><strong>GB/T 1591 Q355</strong></td><td>屈服/抗拉/冲击/焊性逐项对标，取等效；现场以美标 mill certificate 为准</td></tr><tr><td>角钢/钢板/次构件</td><td><strong>ASTM A36</strong>（≥36ksi/250MPa）</td><td><strong>GB/T 700 Q235</strong></td><td>同上</td></tr><tr><td>连接板材/节点板</td><td>A572 Gr.50 或 A992</td><td>GB/T 1591 Q355</td><td>节点受力按 AISC 360 验算</td></tr><tr><td>高强度螺栓</td><td><strong>A325/A490</strong>（摩擦型）+ <strong>AISC S348/RCSC</strong></td><td>GB/T 1228（10.9S）+ GB/T 1231</td><td>扭矩系数/预拉力按美标标定</td></tr><tr><td>普通镀锌螺栓/螺母</td><td><strong>A307 Gr.A + A153/A153M Class C</strong></td><td>GB/T 5782 + <strong>GB/T 13912 镀锌</strong></td><td>镀层厚度按 A153 验收</td></tr><tr><td>剪力连接栓钉</td><td>锻钢有头，<strong>AWS D1.1 Type B</strong></td><td>GB/T 10433（栓钉）</td><td>力学等级/焊接工艺对标</td></tr><tr><td>结构设计/抗震</td><td>AISC 360 + AISC 341 + ASCE 7 + CBC</td><td><strong>GB 50017 / GB 50011</strong></td><td>加州以 AISC/CBC 为验收；中标内部设计参考</td></tr><tr><td>热浸镀锌</td><td>ASTM A123/A153</td><td><strong>GB/T 13912-2002 / GB/T 5267.3</strong> <code>[spec-agent原文]</code></td><td>镀层等级双向核对</td></tr></tbody></table><h3 id="_2-2-材料构件" tabindex="-1">2.2 材料构件 <a class="header-anchor" href="#_2-2-材料构件" aria-label="Permalink to &quot;2.2 材料构件&quot;">​</a></h3><ul><li><strong>主结构</strong>：ASTM A992（W 型）主梁柱/角柱/底盘；ASTM A36 次构件与节点板；全部附材料证书。</li><li><strong>连接受力件</strong>：A325/A490 摩擦型高强螺栓；A307 Gr.A 镀锌普通螺栓/螺母；锻钢有头剪力连接栓钉（AWS D1.1 Type B）<code>[spec-agent 05]</code>。</li><li>冷弯承重墙柱（CFS，如需）：热浸镀锌冷弯钢，依 <strong>AISI S100/S240</strong> + 美国 <strong>ASTM A1003 A 级</strong>；对标中国 GB/T 6723 / JG/T 182。</li></ul><h3 id="_2-3-焊材与工艺" tabindex="-1">2.3 焊材与工艺 <a class="header-anchor" href="#_2-3-焊材与工艺" aria-label="Permalink to &quot;2.3 焊材与工艺&quot;">​</a></h3><ul><li>焊材依 <strong>AWS D1.1</strong>（承重）/ <strong>AWS D1.8</strong>（抗震）规定；PQR/WPS 先行评定；焊工 AWS/CWB 持证。</li><li>剪力连接栓钉焊接同 AWS D1.1 Type B。</li></ul><h3 id="_2-4-防腐" tabindex="-1">2.4 防腐 <a class="header-anchor" href="#_2-4-防腐" aria-label="Permalink to &quot;2.4 防腐&quot;">​</a></h3><ul><li>室外/接触土壤与运输暴露构件按环境类别做涂层或热浸镀锌（ASTM A123/A153）；模块间拼接处现场补涂。</li><li>对标：中国 GB/T 13912 热浸镀锌、GB/T 27806 环氧沥青涂料（内部对标）。</li></ul><hr><h2 id="part-3-—-execution-安装与执行" tabindex="-1">PART 3 — EXECUTION（安装与执行） <a class="header-anchor" href="#part-3-—-execution-安装与执行" aria-label="Permalink to &quot;PART 3 — EXECUTION（安装与执行）&quot;">​</a></h2><h3 id="_3-1-工厂加工与出厂-fc-段" tabindex="-1">3.1 工厂加工与出厂（FC 段） <a class="header-anchor" href="#_3-1-工厂加工与出厂-fc-段" aria-label="Permalink to &quot;3.1 工厂加工与出厂（FC 段）&quot;">​</a></h3><ul><li>框架拼焊→焊检（VT 100% + 关键缝 UT/MT）→底盘校准→栓接扭矩逐栓记录→防腐→<strong>FAT</strong>→加固出厂。</li><li>出厂停点：材料证书齐、焊接/扭矩记录齐、FAT 通过。</li></ul><h3 id="_3-2-现场架设-现场段" tabindex="-1">3.2 现场架设（现场段） <a class="header-anchor" href="#_3-2-现场架设-现场段" aria-label="Permalink to &quot;3.2 现场架设（现场段）&quot;">​</a></h3><ul><li>依批准的架设顺序（<em>Sequence of erection by professional steel structure company</em>）<code>[spec-agent 05]</code>；<strong>专业结构队伍 + 有经验起重/stager</strong> <code>[spec-agent 05]</code>。</li><li>使用移动式起重机、钢制吊索与合适吊装硬件 <code>[源文档 05 50]</code>；吊点经 SE 复核。</li><li><strong>连接前</strong>：校准垂直度/对齐后再螺栓或焊接固定 <code>[源文档 05 50]</code>。</li></ul><h3 id="_3-3-模块间连接执行" tabindex="-1">3.3 模块间连接执行 <a class="header-anchor" href="#_3-3-模块间连接执行" aria-label="Permalink to &quot;3.3 模块间连接执行&quot;">​</a></h3><ul><li>就位→临时支撑→最终连接（栓/焊）→扭矩/焊缝检验→隐蔽前验收。</li><li>摩擦型高强螺栓按 <strong>AISC S348/RCSC</strong> 安装，终拧扭矩成组取样 + 标定留存；扭矩值=工程师设计规定值 <code>[源文档 05 50]</code>。</li><li>现场拼接节点由委派设计出图（连接板/销轴/角柱锁紧），依图执行并<strong>纳入第三方检测</strong>。</li></ul><h3 id="_3-4-检验与停点-hold-points-★★★★" tabindex="-1">3.4 检验与停点（Hold Points）★★★★ <a class="header-anchor" href="#_3-4-检验与停点-hold-points-★★★★" aria-label="Permalink to &quot;3.4 检验与停点（Hold Points）★★★★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>停点</th><th>时机</th><th>验收项</th><th>放行</th></tr></thead><tbody><tr><td><strong>HP-1</strong></td><td>出厂前</td><td>材料证书+焊接记录+扭矩抽查+FAT</td><td>工厂 QAA 签 + insignia</td></tr><tr><td><strong>HP-2</strong></td><td>现场拼接前</td><td>基础/承面交接、锚栓复核（±2mm）、吊装安全交底</td><td>现场验收单</td></tr><tr><td><strong>HP-3</strong></td><td>连接后/隐蔽前</td><td>扭矩记录齐、NDT 通过、第三方结构检验</td><td>NCR 关闭 + 三重放行</td></tr></tbody></table><ul><li>抗震焊缝按 <strong>AWS D1.8</strong>；关键全熔透焊缝按图纸 UT/MT。</li><li>检验嵌入 <strong>Gate 1-6</strong>（见 <code>00_操作手册总纲</code> A.2）：HP-1↔Gate 4，HP-2/3↔Gate 5。</li></ul><h3 id="_3-5-现场清理与保护" tabindex="-1">3.5 现场清理与保护 <a class="header-anchor" href="#_3-5-现场清理与保护" aria-label="Permalink to &quot;3.5 现场清理与保护&quot;">​</a></h3><ul><li>清除焊渣/临时固定件；补涂螺栓界面与防腐；接口面清洁后可隐蔽。</li></ul><hr><h2 id="验收汇总表-可进合同" tabindex="-1">验收汇总表（可进合同） <a class="header-anchor" href="#验收汇总表-可进合同" aria-label="Permalink to &quot;验收汇总表（可进合同）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>性能/验收要求</th><th>标准</th></tr></thead><tbody><tr><td>主框架屈服</td><td>≥345 MPa（50ksi）</td><td>ASTM A992</td></tr><tr><td>高强度螺栓终拧扭矩</td><td>设计规定值，成组标定</td><td>AISC S348/RCSC</td></tr><tr><td>焊缝</td><td>VT 100%；关键缝 NDT(UT/MT) 无裂纹/无熔合不良</td><td>AWS D1.1/D1.8</td></tr><tr><td>锚栓定位</td><td>中心线 ≤ ±2mm（依 Division 03 30）</td><td>ACI 117 / CBC</td></tr><tr><td>检验频率</td><td>新型号 100%→首10台→25%（可降）</td><td>HCD Title 25 §3032</td></tr><tr><td>出厂放行</td><td>insignia + 三重放行</td><td>HSC §19980 + 01 45</td></tr></tbody></table><hr><p><em>本完整 SECTION 由 Modular-Agent 依据 spec-agent 库真实模板条款 <code>[spec-agent 05]</code> + 钢结构源解析 <code>[源文档 05 12/05 50]</code> 编制，作为 05 12 00 的可投用版本；Part 2 中美对应内嵌中国工厂对标需求。共享合规与流程见 <code>00_操作手册总纲</code>、<code>01_共享框架合规底座</code>。</em></p>',43)])])}const A=r(d,[["render",l]]);export{u as __pageData,A as default};
